CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY AUTOINCREMENT,name TEXT NOT NULL UNIQUE COLLATE NOCASE,salt TEXT NOT NULL,hash TEXT NOT NULL,created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id INTEGER PRIMARY KEY AUTOINCREMENT,token_hash TEXT NOT NULL UNIQUE,user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE,ip TEXT,ua TEXT,country TEXT,created INTEGER NOT NULL,last INTEGER NOT NULL,expires INTEGER NOT NULL,dev TEXT);
CREATE INDEX IF NOT EXISTS sess_user ON sessions(user_id);
CREATE TABLE IF NOT EXISTS userdata(user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,data TEXT NOT NULL,rev INTEGER NOT NULL DEFAULT 0,updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS attempts(k TEXT NOT NULL,t INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS att_k ON attempts(k,t);
CREATE TABLE IF NOT EXISTS rooms(code TEXT PRIMARY KEY,host_id INTEGER NOT NULL,title TEXT,qids TEXT NOT NULL,secs INTEGER NOT NULL DEFAULT 0,pen INTEGER NOT NULL DEFAULT 3,created INTEGER NOT NULL,started INTEGER);
CREATE TABLE IF NOT EXISTS room_players(code TEXT NOT NULL,user_id INTEGER NOT NULL,name TEXT NOT NULL,answers TEXT NOT NULL DEFAULT '{}',ok INTEGER NOT NULL DEFAULT 0,err INTEGER NOT NULL DEFAULT 0,done INTEGER NOT NULL DEFAULT 0,joined INTEGER NOT NULL,last INTEGER NOT NULL,PRIMARY KEY(code,user_id));
CREATE TABLE IF NOT EXISTS profiles(user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE,avatar TEXT NOT NULL DEFAULT '',share_online INTEGER NOT NULL DEFAULT 1,share_topic INTEGER NOT NULL DEFAULT 1,share_stats INTEGER NOT NULL DEFAULT 0,last INTEGER NOT NULL DEFAULT 0,label TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS friends(a INTEGER NOT NULL,b INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending',created INTEGER NOT NULL,PRIMARY KEY(a,b));
CREATE INDEX IF NOT EXISTS friends_b ON friends(b);
CREATE TABLE IF NOT EXISTS room_invites(code TEXT NOT NULL,to_id INTEGER NOT NULL,from_id INTEGER NOT NULL,created INTEGER NOT NULL,PRIMARY KEY(code,to_id));
CREATE INDEX IF NOT EXISTS inv_to ON room_invites(to_id);
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY AUTOINCREMENT,from_id INTEGER NOT NULL,to_id INTEGER NOT NULL,kind TEXT NOT NULL,body TEXT NOT NULL,created INTEGER NOT NULL,read INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS msg_to ON messages(to_id,read);
CREATE INDEX IF NOT EXISTS msg_pair ON messages(from_id,to_id,id);
